/* v5: explicit coverage, promise basis and fulfilment milestones. */
function includesAssemblyCapacity(s){return s.scenario!=='ato'||s.assemblyScope!=='modules';}
function getSequence(s){
 const seq=getPlanningSequence(s).filter(id=>id!=='deliver');
 if(s.scenario==='ato'&&!includesAssemblyCapacity(s))seq[seq.indexOf('schedule')]='assemblyDates';
 if(['mts','cto'].includes(s.scenario))seq.splice(seq.indexOf('sync'),0,'availabilityCheck');
 if(s.scenario!=='mts'&&includesAssemblyCapacity(s))seq.splice(seq.indexOf('promise'),0,'capacityDate');
 seq.splice(seq.indexOf('invoice'),0,'delivery','deliver');return seq;
}
function getSteps(s){
 const all=Object.fromEntries(getPlanningSteps(s).map(t=>[t.id,t]));
 const define=(id,owner,icon,title,summary,tasks,output,next,explain)=>({id,owner,icon,title,summary,tasks,output,next,explain});
 const full=includesAssemblyCapacity(s),mts=s.scenario==='mts';
 all.order.tasks.splice(2,0,'Use quotation / pricing and sales-order costing where required; selected BOM content does not always mean creating a separate sales-order BOM master.');
 all.availabilityCheck=define('availabilityCheck','S/4 · Availability / aATP','ClipboardCheck',mts?'Check the finished-printer supply':'Check existing supply for the configuration',mts?`Check availability for ${s.qty} of the matching fixed ${s.heads}-head printer variant.`:'Check relevant existing stock and receipts; a configured printer is not available just because individual modules are in stock.',[
  'Use the defined product, location, stock segment, checking scope and dates.',
  mts?'This reference has prebuilt matching printers. Future receipts may also count under the configured scope.':'The reference proceeds to production planning for final assembly. A supported SBC route can instead plan missing supply during the availability request.',
  'PAL can restrict eligible quantities and ABC can check allowed alternatives if configured. BOP revisits existing confirmations when circumstances change; these are not mandatory serial steps.'
 ],'Material-availability result; no physical stock movement','Use available finished supply or validate missing production before recording the customer promise.','promise');
 all.capacityDate=define('capacityDate','S/4 · PP/DS → customer confirmation','CalendarCheck','Establish the capacity-feasible promise basis',s.scenario==='mto'?'Use the material and resource dates returned by the SBC planning simulation.':'Use the final-assembly plan and relevant material-ready dates to support the customer promise.',[
  'Include the final printer, assembly operations, resources, working calendars and relevant components in the agreed PP/DS scope.',
  'Finite planning must be configured for the constraining resources; using PP/DS does not automatically make every resource finite.',
  s.scenario==='mto'?'This is the result of the SBC simulation, not another full MRP or CTP run.':'Return the planning result through the supported confirmation integration. The chosen route and target release must be validated.'
 ],'Material and finite resource dates support the promise; no date is calculated in this example','Record the agreed customer quantity/date.','capacity-promise');
 all.assemblyDates=define('assemblyDates','S/4 · Production / basic scheduling','CalendarCheck','Date assembly using basic lead time','Only the module prebuilds are in PP/DS in this option. The linked final-assembly order uses basic or lead-time scheduling.',[
  'Allow for selected-module readiness and the maintained assembly duration.',
  'The final assembly line is not checked as a finite PP/DS constraint. A material-covered order can still compete for assembly capacity.',
  'Use this scope only if the business accepts the lead-time assumption; select Modules + final assembly to compare the finite-scheduling design.'
 ],'Material-covered date + basic assembly lead time; no finite assembly-capacity result','Confirm through the supported assembly-processing route.','assembly-scope');
 if(s.scenario==='ato'){
  all.componentCheck.tasks[2]=full?'Component coverage does not prove finite assembly capacity; the next PP/DS planning step validates the scoped resource dates.':'This option uses module coverage and basic assembly lead time. It does not validate finite final-assembly capacity.';
  all.componentCheck.next=full?'Validate final-assembly resource dates before agreeing the promise.':'Apply the basic assembly lead time; finite final-assembly capacity is outside this scope.';
  all.promise.summary=full?'Record the quantity/date from module readiness and the validated final-assembly plan through the supported confirmation route.':'Record the quantity/date using module readiness and basic assembly lead time. This option does not claim a finite assembly-capacity promise.';
  all.promise.tasks[0]=full?'Use the PP/DS material/resource result; validate the assembly-processing / aATP integration for the target edition and release.':'Use the configured component check and assembly lead time; aATP material coverage is not a finite assembly-capacity check.';
  all.promise.explain='assembly-scope';
 }
 all.delivery=define('delivery','S/4 · Logistics (SD-LE)','Truck','Create the outbound delivery and prepare picking',`Create delivery items for ${s.qty} printers with the confirmed quantities, shipping data and applicable stock segment.`,[
  'Check shipping readiness, blocks and the correct fixed variant or customer configuration.',
  'Pick and pack the correct finished-printer stock; complete any required handling or serial-number information.',
  'This milestone does not post goods issue. The example keeps the finished-printer stock and open customer quantity unchanged until the next step.'
 ],'Outbound delivery + picked/packed printers; 0 shipped so far','Post goods issue when the shipment is ready.','fulfilment');
 all.deliver=define('deliver','S/4 · Logistics / Inventory','Truck','Post goods issue for the shipment',`Post goods issue for ${s.qty} finished printers against the outbound delivery.`,[
  'Goods issue reduces the relevant finished-printer stock; a delivery document alone did not do so.',
  `Shipped quantity becomes ${s.qty}; the open quantity on this example order becomes 0.`,
  'Integrate delivery/actuals according to the demand design. In this period example, fulfilled demand stays accounted for so the forecast does not reopen incorrectly.'
 ],`PGI posted · ${s.qty} printers shipped · 0 open`,'Create billing from the delivered quantity and update the connected planning views.','fulfilment');
 all.invoice.title='Bill the delivery and post accounting';all.invoice.summary='Create the billing document, transfer accounting where applicable and reconcile the fulfilment result.';all.invoice.tasks=['Bill the delivered quantity and check accounting status.','Reconcile revenue and production actuals; settle the relevant cost object where the chosen accounting design requires it.','Use actual demand, mix and lead-time performance in the next planning review.'];all.invoice.output='Billing document + accounting; applicable cost settlement';all.invoice.explain='fulfilment';
 return getSequence(s).map(id=>all[id]);
}
Object.assign(SOURCES,{
 aatpOverview:{title:'SAP Help · Advanced Available-to-Promise capabilities',url:'https://help.sap.com/docs/SAP_S4HANA_ON-PREMISE/f132c385e0234fe68ae9ff35b2da178c/00497dff45fa4c50b11be4c653de094d.html'},
 bop:{title:'SAP Help · Backorder Processing',url:'https://help.sap.com/docs/SAP_S4HANA_ON-PREMISE/f132c385e0234fe68ae9ff35b2da178c/73a1a457ef816b10e10000000a441470.html'},
 pmrp:{title:'SAP Help · Predictive Material and Resource Planning',url:'https://help.sap.com/docs/SAP_S4HANA_ON-PREMISE/21aead0c98bd4755abdacd91c99e3393/61d3f1634dae44608b46b79e36d77dfb.html'},
 pmrpAssembly:{title:'SAP Help · Planning at assembly level with pMRP',url:'https://help.sap.com/docs/SAP_S4HANA_ON-PREMISE/feded183701e4ba0b42bc4fc31ad7a12/0e98e873dd4543389a84a7e76138f953.html'},
 avcTrace:{title:'SAP Help · Analysing AVC models with the trace',url:'https://help.sap.com/docs/SAP_S4HANA_CLOUD/f369b2eff700401494ba6e7c9a573288/37e5ba48435348d0b42f3b88fcc21fee.html'},
 fulfilmentFlow:{title:'SAP Help · Delivery, goods issue and billing processing',url:'https://help.sap.com/docs/SAP_S4HANA_ON-PREMISE/21aead0c98bd4755abdacd91c99e3393/e2e82445d3e34c2eaeef2b2b35d2483f-1611.html?version=2023.latest'},
 ctpLegacy:{title:'SAP Help · CTP in SAP APO (terminology reference)',url:'https://help.sap.com/saphelp_scm700_ehp02/helpdata/en/12/42c95360267614e10000000a174cb4/content.htm?no_cache=true'},
 capacitySettings:{title:'SAP Help · Capacity availability settings in Transportation Management',url:'https://help.sap.com/docs/SAP_S4HANA_CLOUD/61e246f4b34c4e1790d8b7651c0b40a8/d05be7c0ad6d4378bccde8fb8e941abc.html'}
});
Object.assign(EXPLANATIONS,{
 'assembly-scope':{title:'ATO: which production is in PP/DS?',body:`<p>Both options prebuild common modules. The difference is whether the <b>final printer and assembly resource</b> also belong to the PP/DS planning scope.</p><table class="difference-table"><thead><tr><th>Modules only</th><th>Modules + final assembly</th></tr></thead><tbody><tr><td>PP/DS schedules the module prebuilds.</td><td>PP/DS schedules module prebuilds and the customer assembly.</td></tr><tr><td>Final assembly uses basic / lead-time scheduling.</td><td>Final assembly is checked against the scoped finite resources and component-ready dates.</td></tr><tr><td>Promise: module readiness + maintained assembly lead time.</td><td>Promise: material readiness + a capacity-feasible assembly result, through supported integration.</td></tr><tr><td>Finite final-assembly capacity is not validated.</td><td>Requires the relevant product, operations, resources, calendars and finite settings.</td></tr></tbody></table><p><b>Canon design question:</b> does the assembly line constrain the service date? The opening reference includes final assembly so the dependency is visible. This is a scope hypothesis to confirm with Canon and the planning expert, not evidence that their line is always the bottleneck. No 1–2 week service guarantee is calculated here.</p><p>Classic assembly processing and an aATP/SBC design are not interchangeable by label. Validate requirement classes, checking methods, configuration support and release compatibility. Stock coverage alone is not a finite-capacity promise.</p><button class="text-link" data-explain="capacity-promise">Capacity-feasible promising, CTP and SBC ↗</button>`,sources:['atoSettings','atoCheck','sbcFeatures']},
 'capacity-promise':{title:'Material availability and capacity-feasible promising',body:`<p>A material check asks whether eligible stock and receipts cover a request. A <b>capacity-feasible promise</b> also needs a production plan that can use the relevant resources at the right time. Calendars, finite settings, operation durations, setup rules and component-ready dates determine that result.</p><p>V5 calls this <b>CTP (Capable-to-Promise)</b>. SAP documents CTP in the older SAP APO Global ATP context. In the S/4 aATP route illustrated here, <b>Supply Creation-Based Confirmation (SBC)</b> calls PP/DS to plan the new requirement. Its result supports the confirmation; the diagram does not add a second mandatory CTP run.</p><p>For configured products, validate <b>PPAC / CDP</b>, the master data and supported features in the target release. PP/DS can use finite or infinite planning: select finite settings for the resources that must constrain the promise. The CTO reference plans first, then confirms; SBC is a supported alternative to evaluate. ATO's linked assembly route also needs a validated confirmation integration.</p><p>The similarly named <b>Capacity Availability Settings</b> app documented in SAP Help belongs to <b>Transportation Management</b>. It is not used here as evidence of finite printer-assembly capacity.</p><button class="text-link" data-explain="sbc">How the MTO SBC simulation works ↗</button>`,sources:['sbc','sbcFeatures','ctpLegacy','capacitySettings']},
 pal:{title:'PAL · Product Allocation',body:`<p>Product Allocation can limit what a customer or segment may receive in an allocation period. Physical stock may exist while the allocated quantity still restricts confirmation.</p><p>It is an optional confirmation policy. It does not manufacture supply, consume the forecast or prove finite production capacity. Decide the allocation dimensions, periods and quantities, then validate the supported checking route for Canon.</p>`,sources:['aatpOverview','sbcFeatures']},
 abc:{title:'ABC · Alternative-Based Confirmation',body:`<p>ABC can evaluate permitted alternatives when the original request cannot be met, for example a different supplying plant or a supported substitute product. Each alternative still needs its own availability result.</p><p>A 5-head module cannot silently replace a requested 7-head configuration. Any substitute must be technically valid and commercially accepted. The configuration and customer promise must remain consistent.</p><p>This is an optional branch, not a mandatory step. SAP's current SBC feature table lists ABC with SBC but restricts combining it with CDP in the PPAC route. Do not assume this capability is available for every configured-printer check.</p>`,sources:['aatpOverview','sbcFeatures']},
 bop:{title:'BOP · Backorder Processing',body:`<p>BOP rechecks existing confirmations when demand or supply changes. Examples include a cancelled order, a larger customer request or a delayed receipt. Priorities determine which orders keep or receive available quantities and dates.</p><p>It belongs to confirmation review after a change, not automatically between every initial ATP check and confirmation. In the documented PAC-with-supply-creation route, a BOP run performs PAC and does <b>not trigger SBC supply creation</b>. Validate its compatibility with the selected configured-product route.</p><p>A changed date may require customer follow-up and changes to execution. BOP does not physically move stock or rewrite a configurator model.</p>`,sources:['bop','sbcFeatures']},
 pmrp:{title:'pMRP · an optional planning simulation',body:`<p>Predictive Material and Resource Planning uses simplified demand and manufacturing data to identify potential capacity problems early and compare responses. A planner can explore preproduction, resource changes or make-or-buy decisions before adopting a result.</p><p>It is useful for the forecast-driven scope: finished variants in MTS and prebuilt modules in ATO. The chosen CTO reference also prebuilds modules, so the same upstream scope can be evaluated. Applicability follows the demand and stock design, not just the scenario name. This MTO example has no advance prebuild.</p><p>pMRP is not the finite order-confirmation check or the execution schedule. A released simulation can create PIRs or capacity proposals under the supported settings. Agree which plan owns demand before transferring anything; do not duplicate IBP-owned proposals with another independent PIR plan.</p>`,sources:['pmrp','pmrpAssembly']},
 fulfilment:{title:'Delivery, goods issue, billing and actuals',body:`<ol><li><b>Create outbound delivery:</b> copy relevant order quantities and shipping data, check readiness, then pick and pack the correct printer stock.</li><li><b>Post goods issue (PGI):</b> reduce the applicable finished-printer inventory and record the shipment. In this example the open order quantity becomes zero here.</li><li><b>Billing and accounting:</b> invoice delivered quantities, check the accounting transfer and reconcile actuals. Cost settlement follows the chosen production / sales-order cost-object design.</li><li><b>Planning feedback:</b> map delivered quantities and actuals consistently so fulfilled demand remains accounted for, then review the next forecast and module mix.</li></ol><p>Creating a delivery document is not the same as shipping the printer. The quantities below the diagram show this distinction. Shipment, billing, financial closure and forecast revision are separate events.</p>`,sources:['fulfilmentFlow']},
 'model-tools':{title:'AVC modelling, simulation and trace',body:`<p>AVC offers modelling and simulation tools, including a trace to help analyse how the model processes a configuration. Use them to maintain rules and explain why a concrete characteristic combination is allowed or rejected.</p><p>These tools complement the configurable material, class 300, configuration profile, dependencies, super-BOM and routing. Classic VC already supports constraints and variant tables; AVC adds capabilities such as negative variant tables.</p><p>They do not forecast the attachment-rate mix or schedule finite assembly capacity. The full production and fulfilment lanes remain visible for either engine; interface support still needs validation.</p>`,sources:['vc','avc','avcTrace']}
});
EXPLANATIONS['ato-check'].body+=`<p>The ATO PP/DS scope control lets you compare basic final-assembly dating with a scope that includes finite assembly scheduling.</p><button class="text-link" data-explain="assembly-scope">Compare the two assembly scopes ↗</button>`;
EXPLANATIONS.assumptions.body+=`<p><b>V5 coverage:</b> all four reference routes show both VC and AVC, explicit customer demand, confirmation, production, delivery creation, goods issue and billing. Dashed capability cards are optional and do not advance the example order. ATO defaults to module plus final-assembly scheduling; the alternative excludes finite final-assembly capacity.</p>`;
Object.assign(TERMS,{
 'CTP / capacity-feasible promise':'A promise supported by relevant material and finite resource dates. CTP is documented in SAP APO; the S/4 order-entry example uses SBC + PP/DS.',
 'pMRP':'An optional early capacity / supply simulation using simplified requirements and master data. It is separate from finite execution scheduling.',
 'PGI':'Post Goods Issue: the shipment milestone that reduces the applicable finished-printer stock.'
});
function renderCoverage(){
 const body=[
  ['Configuration foundation','KMAT / class 300, profile, dependencies, super-BOM / routing; manufacturing source / PDS','vc'],
  ['AVC tools','Visible AVC modelling / simulation card; all operational lanes shown in full','model-tools'],
  ['Demand Management','Fixed-variant PIR + customer demand','Customer requirement; no parent PIR','Module PIR + selected customer need','Module PIR + linked assembly component need','consumption'],
  ['Advance supply','Finished variants + components','No prebuild in this example','Common modules','Common modules','supply'],
  ['pMRP simulation','Optional for forecast scope','No prebuild scope here','Optional for prebuilt modules','Optional for prebuilt modules','pmrp'],
  ['Order-driven PP/DS','Prebuild scheduling; no assembly for this order','SBC supply simulation + subsequent schedule','Final assembly planning + scheduling',includesAssemblyCapacity(state)?'Modules + finite final assembly':'Modules only; basic final-assembly dates','assembly-scope'],
  ['Promise basis','Matching finished-printer stock / receipts','Material + configured finite resource result from SBC','Material + final-assembly planning result',includesAssemblyCapacity(state)?'Module readiness + finite assembly plan':'Module readiness + basic assembly lead time','capacity-promise'],
  ['Availability policies','PAL / ABC optional; BOP on changes. Checking-route compatibility matters.','promise'],
  ['Production / stock','Receipt before order','Order-specific production + inspection / GR','Module issue → assembly + inspection / GR','Linked assembly → module issue → inspection / GR','execution'],
  ['Delivery → PGI → billing','Three separate milestones, accounting and actuals; settlement where applicable','fulfilment']
 ];
 const keys=['mts','mto','cto','ato'];
 $('#coverage').innerHTML=`<section class="panel coverage-panel"><div class="section-row"><div><p class="eyebrow">PROCESS COVERAGE · ALL 8 SCENARIO / ENGINE ROUTES</p><h3>Shared layers and deliberate differences</h3></div><button class="text-link" data-explain="assembly-scope">ATO assembly scope ↗</button></div><p>Each route is drawn in full for Classic VC and AVC. Optional and out-of-scope capabilities are labelled, rather than treated as missing steps. Supply ownership follows the selected design; ATO assembly scope follows the control in Order process.</p><div class="compare-table-wrap"><table class="compare-table coverage-table"><thead><tr><th>Layer / responsibility</th>${keys.map(k=>`<th>${k.toUpperCase()}<small>Classic VC + AVC</small></th>`).join('')}</tr></thead><tbody>${body.map(row=>{const shared=row.length===3,explain=row[row.length-1];return `<tr><th><button class="text-link" data-explain="${explain}">${row[0]} ↗</button></th>${keys.map((k,i)=>`<td class="${k==='ato'?'ato-column':''}">${shared?row[1]:row[i+1]}</td>`).join('')}</tr>`;}).join('')}<tr><th>Open the complete diagram</th>${keys.map(k=>`<td>${['VC','AVC'].map(engine=>`<button class="text-link" data-open-route="${k}" data-route-engine="${engine}">${engine==='VC'?'Classic VC':'AVC'} →</button>`).join('<br>')}</td>`).join('')}</tr></tbody></table></div><p class="small muted">The matrix compares the selected reference designs. It does not assert that every SAP feature is supported by every edition, release or configuration interface.</p></section>`;
}
